code.cpp:
class Solution {
public:
    int minDeletions(vector<int>& nums) {
        int deletions = 0;
        for (int i = 1; i < (int)nums.size(); ++i) {
            if (nums[i] == nums[i - 1]) ++deletions;
        }
        return deletions;
    }
};

code.java:
class Solution {
    public int minDeletions(int[] nums) {
        int deletions = 0;
        for (int i = 1; i < nums.length; ++i) {
            if (nums[i] == nums[i - 1]) {
                ++deletions;
            }
        }
        return deletions;
    }
}

code.python3:
class Solution:
    def minDeletions(self, nums: list[int]) -> int:
        deletions = 0
        for i in range(1, len(nums)):
            if nums[i] == nums[i - 1]:
                deletions += 1
        return deletions

